2	// Loads the ElevenLabs key at runtime. Never log or persist it.
3	// Order: process.env.ELEVENLABS_API_KEY, then /Users/mrnetwork/Syntura/video/.env.
4	import { readFileSync, existsSync } from "node:fs";
5	import { dirname, join } from "node:path";
6	import { fileURLToPath } from "node:url";
7	
8	export const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
9	const KEY_FILE = "/Users/mrnetwork/Syntura/video/.env";
10	
11	function load() {
12	  if (process.env.ELEVENLABS_API_KEY) return process.env.ELEVENLABS_API_KEY.trim();
13	  if (existsSync(KEY_FILE)) {
14	    for (const line of readFileSync(KEY_FILE, "utf8").split("\n")) {
15	      const m = line.match(/^\s*(?:export\s+)?ELEVENLABS_API_KEY\s*=\s*(.*?)\s*$/);
16	      if (m) return m[1].replace(/^["']|["']$/g, "");
17	    }
18	  }
19	  return null;
20	}
21	
22	export const key = load();
23	if (!key) {
24	  console.error("ELEVENLABS_API_KEY not found (env or Syntura/video/.env).");
25	  process.exit(1);
26	}
27	
28	export const API = "https://api.elevenlabs.io/v1";
29	
30	export async function retry(fn, tries = 4) {
31	  let last;
32	  for (let i = 1; i <= tries; i++) {
33	    try { return await fn(); } catch (e) {
34	      last = e;
35	      if (/\b(401|402|403|422)\b/.test(String(e.message))) break; // not retryable
36	      await new Promise((r) => setTimeout(r, 1500 * i));
37	    }
38	  }
39	  throw last;
40	}
41	
42	// Error text never includes the key (we only echo response bodies).
43	export async function post(path, body) {
44	  const res = await fetch(API + path, {
45	    method: "POST",
46	    headers: { "xi-api-key": key, "content-type": "application/json" },
47	    body: JSON.stringify(body),
48	  });
49	  if (!res.ok) throw new Error(`${res.status} ${(await res.text()).slice(0, 300)}`);
50	  return res;
51	}
