53	// Voice-over for every line in script.json, via ElevenLabs /with-timestamps.
54	//   node scripts/voiceover.mjs              generate changed/missing lines (hash cache)
55	//   ONLY=problem_2 node scripts/voiceover.mjs   force one or more ids (comma list)
56	// Outputs:
57	//   public/audio/vo/<sceneId>_<i>.mp3        (what the film plays; loudness-normalised to -16 LUFS)
58	//   .cache/raw/<sceneId>_<i>.mp3             (untouched take; timing.mjs may atempo from it)
59	//   .cache/words/<sceneId>_<i>.json          (word timings in seconds, from char alignment)
60	//   .cache/vo.json                           (hash per line + chars consumed log)
61	import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
62	import { execFileSync } from "node:child_process";
63	import { createHash } from "node:crypto";
64	import { join } from "node:path";
65	import { ROOT, post, retry } from "./env.mjs";
66	import { renderVo } from "./vofx.mjs";
67	
68	const script = JSON.parse(readFileSync(join(ROOT, "script.json"), "utf8"));
69	const OUT = join(ROOT, "public/audio/vo");
70	const RAW = join(ROOT, ".cache/raw");
71	const WORDS = join(ROOT, ".cache/words");
72	const CACHE = join(ROOT, ".cache/vo.json");
73	for (const d of [OUT, RAW, WORDS]) mkdirSync(d, { recursive: true });
74	const cache = existsSync(CACHE) ? JSON.parse(readFileSync(CACHE, "utf8")) : { lines: {}, charsUsed: 0 };
75	
76	// Per-line performance direction (overrides merged over the voice settings).
77	const OVERRIDES = {
78	  // The anchor: crisp and neutral, a newsroom read.
79	  open_0: { stability: 0.7, style: 0.1, speed: 1.0 },
80	  // The date line: a beat slower, a little weight.
81	  open_1: { stability: 0.5, style: 0.3, speed: 0.92 },
82	  turn_0: { stability: 0.55, style: 0.3, speed: 0.9 },
83	  unique_0: { speed: 0.96 },
84	  // The close: slow and settled.
85	  close_0: { stability: 0.6, style: 0.3, speed: 0.85 },
86	};
87	
88	const only = process.env.ONLY ? process.env.ONLY.split(",") : null;
89	
90	export const durationOf = (f) =>
91	  parseFloat(execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "default=nw=1:nk=1", f]).toString());
92	
93	function toWords(a) {
94	  const words = [];
95	  let cur = null;
96	  a.characters.forEach((ch, i) => {
97	    if (/\s/.test(ch)) { if (cur) { words.push(cur); cur = null; } return; }
98	    if (!cur) cur = { word: "", start: a.character_start_times_seconds[i], end: 0 };
99	    cur.word += ch;
100	    cur.end = a.character_end_times_seconds[i];
101	  });
102	  if (cur) words.push(cur);
103	  return words;
104	}
105	
106	async function synth(text, voiceId, settings) {
107	  return retry(async () => {
108	    const res = await post(`/text-to-speech/${voiceId}/with-timestamps?output_format=mp3_44100_128`, {
109	      text, model_id: script.model, voice_settings: settings,
110	    });
111	    const body = await res.json();
112	    return { audio: Buffer.from(body.audio_base64, "base64"), words: toWords(body.alignment) };
113	  });
114	}
115	
116	// Speech rate sanity: normal read is ~11-18 chars/sec of speech.
117	const sane = (text, words) => {
118	  const speech = words.at(-1).end - words[0].start;
119	  const cps = text.length / speech;
120	  return { ok: cps >= 8 && cps <= 21, cps };
121	};
122	
123	let used = 0;
124	for (const scene of script.scenes) {
125	  for (const [i, line] of scene.lines.entries()) {
126	    const id = `${scene.id}_${i}`;
127	    const voice = script.voices[line.voice];
128	    const settings = { ...voice.settings, ...(OVERRIDES[id] || {}) };
129	    const hash = createHash("sha1").update(JSON.stringify([line.text, voice.id, settings, script.model])).digest("hex");
130	    const have = existsSync(join(OUT, `${id}.mp3`)) && existsSync(join(WORDS, `${id}.json`));
131	    if (have && cache.lines[id]?.hash === hash && !(only && only.includes(id))) { console.log(`${id}: cached`); continue; }
132	    if (only && !only.includes(id) && have) continue;
133	
134	    let take = await synth(line.text, voice.id, settings);
135	    used += line.text.length;
136	    let chk = sane(line.text, take.words);
137	    if (!chk.ok) {
138	      console.log(`${id}: ${chk.cps.toFixed(1)} cps looks off, retaking once`);
139	      const again = await synth(line.text, voice.id, settings);
140	      used += line.text.length;
141	      const chk2 = sane(line.text, again.words);
142	      if (Math.abs(chk2.cps - 14) < Math.abs(chk.cps - 14)) { take = again; chk = chk2; }
143	    }
144	    writeFileSync(join(RAW, `${id}.mp3`), take.audio);
145	    renderVo(id, 1);
146	    writeFileSync(join(WORDS, `${id}.json`), JSON.stringify({ tempo: 1, words: take.words }, null, 1));
147	    const dur = durationOf(join(OUT, `${id}.mp3`));
148	    cache.lines[id] = { hash, voice: voice.id, chars: line.text.length, dur };
149	    console.log(`${id}: ${dur.toFixed(2)}s  ${chk.cps.toFixed(1)} cps  [${line.voice}/${voice.id}]`);
150	  }
151	}
152	cache.charsUsed = (cache.charsUsed || 0) + used;
153	writeFileSync(CACHE, JSON.stringify(cache, null, 1));
154	console.log(`chars this run: ${used}, total logged: ${cache.charsUsed}`);
155	=== scripts/vofx.mjs
156	// Renders a VO clip from its untouched take: .cache/raw/<id>.mp3 -> [atempo] -> loudnorm -16 LUFS
157	// (two-pass, TP -1.5) -> public/audio/vo/<id>.mp3. Shared by voiceover.mjs and timing.mjs.
158	import { spawnSync, execFileSync } from "node:child_process";
159	import { join } from "node:path";
160	import { fileURLToPath } from "node:url";
161	
162	const ROOT = join(fileURLToPath(import.meta.url), "../..");
163	export const VO_LUFS = -16;
164	const BROADCAST = new Set(["open_0"]);
165	
166	export function renderVo(id, tempo = 1) {
167	  const src = join(ROOT, ".cache/raw", `${id}.mp3`);
168	  const dst = join(ROOT, "public/audio/vo", `${id}.mp3`);
169	  // The breaking-news line plays as a broadcast: band-limited and pressed.
170	  const tv = BROADCAST.has(id) ? "highpass=f=260,lowpass=f=5200,acompressor=threshold=-20dB:ratio=4:attack=5:release=60," : "";
171	  const pre = (tempo !== 1 ? `atempo=${tempo},` : "") + tv;
172	  const ln = `loudnorm=I=${VO_LUFS}:TP=-1.5:LRA=11`;
173	  const r = spawnSync("ffmpeg", ["-hide_banner", "-nostats", "-i", src, "-af", `${pre}${ln}:print_format=json`, "-f", "null", "-"], { encoding: "utf8" });
174	  const m = JSON.parse(r.stderr.slice(r.stderr.lastIndexOf("{"), r.stderr.lastIndexOf("}") + 1));
175	  const af = `${pre}${ln}:measured_I=${m.input_i}:measured_TP=${m.input_tp}:measured_LRA=${m.input_lra}:measured_thresh=${m.input_thresh}:offset=${m.target_offset}:linear=true`;
176	  execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-i", src, "-af", af, "-ar", "44100", "-b:a", "128k", dst]);
177	}
178	=== scripts/timing.mjs
179	// Builds src/timing.json (absolute frames @30fps) from script.json + generated VO.
180	//   node scripts/timing.mjs
181	// Reads word timings from .cache/words/*.json and music bpm/offset from .cache/music.json
182	// (written by music.mjs; falls back to 100 bpm, offset 0).
183	// Budget: 3510f (117s). Voices play at natural pace (no atempo). If over, it tightens gaps,
184	// then trims planned scene length where there is picture slack after the VO, in TRIM_ORDER
185	// (montage first, then idea, then the demo scenes). The close always keeps >= 60f after its last word.
186	import { readFileSync, writeFileSync, existsSync } from "node:fs";
187	import { execFileSync } from "node:child_process";
188	import { join } from "node:path";
189	import { fileURLToPath } from "node:url";
190	
191	const ROOT = join(fileURLToPath(import.meta.url), "../..");
192	const FPS = 30, MAX = 5250; // 2:55 ceiling
193	const END_HOLD = { close: 150, turn: 24 }; // min frames after last word, per scene
194	const TRIM_ORDER = ["sense", "graph", "reason", "decide", "act", "evidence", "problem", "gap", "unique"];
195	const script = JSON.parse(readFileSync(join(ROOT, "script.json"), "utf8"));
196	const dur = (f) => parseFloat(execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "default=nw=1:nk=1", f]).toString());
197	const wordsOf = (id) => JSON.parse(readFileSync(join(ROOT, ".cache/words", `${id}.json`), "utf8"));
198	
199	const LOOSE = { lead: 12, dialogue: 10, narration: 16, tail: 16 };
200	const TIGHT = { lead: 8, dialogue: 6, narration: 8, tail: 8 };
201	
202	function build(sp, trim = {}) {
203	  let t = 0;
204	  const scenes = [];
205	  for (const scene of script.scenes) {
206	    const from = t;
207	    let cur = from + sp.lead;
208	    let prevVoice = null;
209	    const lines = [];
210	    for (const [i, line] of scene.lines.entries()) {
211	      const id = `${scene.id}_${i}`;
212	      if (prevVoice) cur += prevVoice === "narrator" || line.voice === "narrator" ? sp.narration : sp.dialogue;
213	      const { tempo, words } = wordsOf(id);
214	      const file = `audio/vo/${id}.mp3`;
215	      const fileFrames = Math.ceil(dur(join(ROOT, "public", file)) * FPS);
216	      const w = words.map((x) => ({
217	        word: x.word,
218	        start: cur + Math.round((x.start / tempo) * FPS),
219	        end: cur + Math.max(1, Math.round((x.end / tempo) * FPS)),
220	      }));
221	      const speechEnd = w.at(-1).end;
222	      lines.push({ voice: line.voice, text: line.text, file, startFrame: cur, durationFrames: fileFrames, speechEndFrame: speechEnd, words: w });
223	      cur = speechEnd;
224	      prevVoice = line.voice;
225	    }
226	    const durationInFrames = Math.max(scene.seconds * FPS - (trim[scene.id] || 0), cur + Math.max(sp.tail, END_HOLD[scene.id] || 0) - from);
227	    // keep each clip inside its scene (trailing mp3 silence only)
228	    for (const l of lines) l.durationFrames = Math.min(l.durationFrames, from + durationInFrames - l.startFrame);
229	    scenes.push({ id: scene.id, from, durationInFrames, plannedFrames: scene.seconds * FPS, lines });
230	    t = from + durationInFrames;
231	  }
232	  return { scenes, totalFrames: t };
233	}
234	
235	let sp = LOOSE;
236	let res = build(sp);
237	if (res.totalFrames > MAX) { sp = TIGHT; res = build(sp); console.log(`over budget with loose spacing; tightened -> ${res.totalFrames}f`); }
238	
239	// Then trim planned lengths in TRIM_ORDER, keeping >= RESERVE frames of picture after each scene's VO.
240	const RESERVE = 45;
241	const trim = {};
242	if (res.totalFrames > MAX) {
243	  let left = res.totalFrames - MAX;
244	  for (const id of TRIM_ORDER) {
245	    if (left <= 0) break;
246	    const s = res.scenes.find((x) => x.id === id);
247	    const voEnd = s.lines.at(-1).words.at(-1).end - s.from;
248	    const n = Math.min(left, Math.max(0, s.durationInFrames - voEnd - RESERVE));
249	    if (n) { trim[id] = n; left -= n; }
250	  }
251	  res = build(sp, trim);
252	  console.log(`trimmed: ${Object.entries(trim).map(([k, v]) => `${k}-${v}`).join(" ") || "none"}`);
253	  if (res.totalFrames > MAX) console.error(`STILL OVER: ${res.totalFrames}f > ${MAX}f`);
254	}
255	
256	const music = existsSync(join(ROOT, ".cache/music.json")) ? JSON.parse(readFileSync(join(ROOT, ".cache/music.json"), "utf8")) : {};
257	const bpm = music.bpm || 100;
258	const offset = music.offsetSec || 0;
259	const beats = [];
260	for (let b = offset; b * FPS < res.totalFrames; b += 60 / bpm) beats.push(Math.round(b * FPS));
261	
262	const out = {
263	  fps: FPS,
264	  totalFrames: res.totalFrames,
265	  bpm,
266	  beats,
267	  music: { file: "audio/music.mp3", source: music.source || "unknown" },
268	  scenes: res.scenes.map(({ plannedFrames, ...s }) => ({ ...s, lines: s.lines.map(({ speechEndFrame, ...l }) => l) })),
269	};
270	writeFileSync(join(ROOT, "src/timing.json"), JSON.stringify(out, null, 1));
271	
272	const tempos = res.scenes.flatMap((s) => s.lines.map((_, i) => `${s.id}_${i}`)).map((id) => [id, wordsOf(id).tempo]).filter(([, t]) => t !== 1);
273	console.log(`spacing: ${sp === LOOSE ? "loose" : "tight"}; atempo lines: ${tempos.map(([id, t]) => `${id}x${t}`).join(" ") || "none"}`);
274	console.log("scene        from   dur(f)  planned  sec    lines words");
275	for (const s of res.scenes) {
276	  console.log(`${s.id.padEnd(12)} ${String(s.from).padStart(5)} ${String(s.durationInFrames).padStart(7)} ${String(s.plannedFrames).padStart(8)} ${(s.durationInFrames / FPS).toFixed(1).padStart(5)} ${String(s.lines.length).padStart(6)} ${String(s.lines.reduce((n, l) => n + l.words.length, 0)).padStart(5)}`);
277	}
278	console.log(`total ${res.totalFrames}f = ${(res.totalFrames / FPS).toFixed(2)}s (max ${MAX}), bpm ${bpm}, ${beats.length} beats`);
279	=== scripts/music.mjs
280	// Music bed -> public/audio/music.mp3, sized to src/timing.json totalFrames/30 + 2s.
281	//   node scripts/music.mjs            (skips if music.mp3 exists; FORCE=1 to redo)
282	// Path A: ElevenLabs Music API (POST /v1/music). Path B (fallback): several looped
283	// sound-generation beds stitched with ffmpeg crossfades. Writes .cache/music.json
284	// { source, bpm, offsetSec } for timing.mjs (beats).
285	import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
286	import { execFileSync } from "node:child_process";
287	import { join } from "node:path";
288	import { ROOT, post, retry } from "./env.mjs";
289	
290	const OUT = join(ROOT, "public/audio/music.mp3");
291	const META = join(ROOT, ".cache/music.json");
292	mkdirSync(join(ROOT, ".cache/music"), { recursive: true });
293	const timing = existsSync(join(ROOT, "src/timing.json")) ? JSON.parse(readFileSync(join(ROOT, "src/timing.json"), "utf8")) : { totalFrames: 3540 };
294	const seconds = Math.ceil(timing.totalFrames / 30 + 2);
295	
296	const PROMPT =
297	  "Modern cinematic electronic score for a fintech product film about markets and supply chains, about 104 BPM, precise and confident, no vocals. 0-17s: night newsroom tension, a low sub rumble, a ticking clock-like hi-hat, sparse glitchy blips, a single held synth note. 17-52s: tension builds steadily, a pulsing arpeggiated synth bass, data-like plucks, the kick enters softly, a sense of a chain reaction spreading. 52-65s: suspense, the drums drop out, a rising airy riser building to a peak. At 65s: a clean bright hit and release into a confident groove. 65-145s: forward-moving minimal electronic groove, crisp tight percussion, warm analog bass, bright precise plucks, steady and intelligent, building gradually in layers. 145-162s: the arrangement opens wider and lifts, more energy, a feeling of clarity. 162-172s: resolves on a clean final chord and one soft final hit, then a short airy tail. No vocals, no lyrics.";
298	
299	const ff = (a) => execFileSync("ffmpeg", ["-y", "-loglevel", "error", ...a]);
300	const dur = (f) => parseFloat(execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "default=nw=1:nk=1", f]).toString());
301	
302	// Rough BPM + first-beat offset from an onset envelope (low-passed energy, 10ms hops) via autocorrelation.
303	function detectBpm(file) {
304	  const raw = execFileSync("ffmpeg", ["-loglevel", "error", "-i", file, "-t", "60", "-ac", "1", "-ar", "8000", "-af", "lowpass=f=200", "-f", "s16le", "-"], { maxBuffer: 1 << 28 });
305	  const s = new Int16Array(raw.buffer, raw.byteOffset, raw.length >> 1);
306	  const hop = 80; // 10ms
307	  const env = [];
308	  for (let i = 0; i + hop <= s.length; i += hop) { let e = 0; for (let j = 0; j < hop; j++) e += s[i + j] * s[i + j]; env.push(Math.sqrt(e / hop)); }
309	  const on = env.map((v, i) => Math.max(0, v - (env[i - 1] ?? v)));
310	  let best = { bpm: 100, score: -1 };
311	  for (let bpm = 80; bpm <= 140; bpm += 0.5) {
312	    const lag = 6000 / bpm; // in 10ms hops
313	    let sc = 0;
314	    for (let i = 0; i + lag * 2 < on.length; i++) sc += on[i] * (on[Math.round(i + lag)] + on[Math.round(i + 2 * lag)]);
315	    if (sc > best.score) best = { bpm, score: sc };
316	  }
317	  // phase: best offset within one beat
318	  const lag = 6000 / best.bpm;
319	  let ph = { off: 0, sc: -1 };
320	  for (let o = 0; o < lag; o++) { let sc = 0; for (let t = o; t < on.length; t += lag) sc += on[Math.round(t)] || 0; if (sc > ph.sc) ph = { off: o, sc }; }
321	  return { bpm: best.bpm, offsetSec: +(ph.off / 100).toFixed(3) };
322	}
323	
324	if (existsSync(OUT) && !process.env.FORCE) {
325	  console.log("music.mp3 exists (FORCE=1 to regenerate)");
326	} else {
327	  let source;
328	  try {
329	    const buf = await retry(async () => {
330	      const res = await post("/music?output_format=mp3_44100_128", { prompt: PROMPT, music_length_ms: seconds * 1000, force_instrumental: true });
331	      return Buffer.from(await res.arrayBuffer());
332	    }, 2);
333	    writeFileSync(OUT, buf);
334	    source = "elevenlabs-music";
335	  } catch (e) {
336	    console.error(`Music API unavailable (${e.message.slice(0, 160)}); falling back to sound-generation beds`);
337	    const BEDS = [
338	      ["tense", "Tense low synth pulse loop with muted kick like a racing heartbeat, 100 bpm, minimal electronic, sparse, no vocals", 17],
339	      ["swell", "Reversed cinematic swell rising into silence, 100 bpm, no drums", 5],
340	      ["groove", "Confident uplifting minimal electronic groove loop, 100 bpm, crisp percussion, warm plucks, no vocals", 22],
341	      ["build", "Rising optimistic minimal electronic groove loop building energy, 100 bpm, crisp hats, warm plucks, no vocals", 22],
342	      ["outro", "Soft resolving minimal electronic outro, 100 bpm, warm pads, ends with one clean final hit, no vocals", 12],
343	    ];
344	    const parts = [];
345	    for (const [n, text, d] of BEDS) {
346	      const f = join(ROOT, ".cache/music", `${n}.mp3`);
347	      if (!existsSync(f)) {
348	        const res = await retry(() => post("/sound-generation?output_format=mp3_44100_128", { text, duration_seconds: d, prompt_influence: 0.5 }));
349	        writeFileSync(f, Buffer.from(await res.arrayBuffer()));
350	      }
351	      parts.push(f);
352	    }
353	    // layout: tense(loop to 17s) swell(5) groove(loop) build(loop) outro(12) with 1s crossfades
354	    const grooveLen = (seconds - 17 - 5 - 12) / 2 + 2;
355	    const segs = [[parts[0], 17.5], [parts[1], 5.5], [parts[2], grooveLen], [parts[3], grooveLen], [parts[4], 12]];
356	    const inputs = segs.flatMap(([f]) => ["-stream_loop", "-1", "-i", f]);
357	    let fc = segs.map(([, d], i) => `[${i}:a]atrim=0:${d},asetpts=PTS-STARTPTS[s${i}]`).join(";");
358	    let prev = "s0";
359	    for (let i = 1; i < segs.length; i++) { fc += `;[${prev}][s${i}]acrossfade=d=1[x${i}]`; prev = `x${i}`; }
360	    fc += `;[${prev}]atrim=0:${seconds},afade=t=out:st=${seconds - 1.5}:d=1.5[out]`;
361	    ff([...inputs, "-filter_complex", fc, "-map", "[out]", "-b:a", "192k", OUT]);
362	    source = "sound-generation-stitched";
363	  }
364	  const beat = detectBpm(OUT);
365	  writeFileSync(META, JSON.stringify({ source, ...beat, seconds }, null, 1));
366	}
367	const meta = JSON.parse(readFileSync(META, "utf8"));
368	console.log(`music.mp3 ${dur(OUT).toFixed(1)}s (target ${seconds}s) via ${meta.source}; bpm ~${meta.bpm}, first beat ${meta.offsetSec}s`);
369	console.log("re-run: node scripts/timing.mjs  (to write bpm/beats)");
370	=== scripts/sfx.mjs
371	// Sound effects via ElevenLabs /v1/sound-generation. Skips files that already exist.
372	//   node scripts/sfx.mjs                 all missing
373	//   ONLY=stamp,impact node scripts/sfx.mjs   force regenerate some
