503	// Minimal Chrome DevTools harness for the capture scripts: launch headless
504	// Chrome, evaluate JS, click by text, capture screenshots of the page or one
505	// element, and record a screencast of the page to JPEG frames with timestamps
506	// (turned into clips with ffmpeg afterwards by scripts/encode.mjs).
507	import { spawn } from "node:child_process";
508	import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
509	import { tmpdir } from "node:os";
510	import { join } from "node:path";
