512	const CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome";
513	export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
514	
515	export async function launch({ width = 1440, height = 900, extraArgs = [] } = {}) {
516	  const port = 9600 + Math.floor(Math.random() * 300);
517	  const chrome = spawn(
518	    CHROME,
519	    [
520	      "--headless=new",
521	      "--hide-scrollbars",
522	      "--no-first-run",
523	      "--no-default-browser-check",
524	      "--autoplay-policy=no-user-gesture-required",
525	      "--disable-background-timer-throttling",
526	      "--disable-renderer-backgrounding",
527	      `--remote-debugging-port=${port}`,
528	      `--user-data-dir=${mkdtempSync(join(tmpdir(), "cascadr-cdp-"))}`,
529	      `--window-size=${width},${height}`,
530	      ...extraArgs,
531	      "about:blank",
532	    ],
533	    { stdio: "ignore" },
534	  );
535	  let targets = null;
536	  for (let i = 0; i < 80 && !targets; i++) {
537	    await sleep(250);
538	    try {
539	      targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json();
540	    } catch {}
541	  }
542	  if (!targets) throw new Error("Chrome did not start");
543	  const ws = new WebSocket(targets.find((t) => t.type === "page").webSocketDebuggerUrl);
544	  await new Promise((r) => (ws.onopen = r));
545	  let seq = 0;
546	  const pending = new Map();
547	  const listeners = new Map();
548	  const consoleLines = [];
549	  ws.onmessage = (e) => {
550	    const m = JSON.parse(e.data);
551	    if (m.id && pending.has(m.id)) {
552	      pending.get(m.id)(m);
553	      pending.delete(m.id);
554	      return;
555	    }
556	    if (m.method === "Runtime.consoleAPICalled" && ["error", "warning"].includes(m.params.type)) {
557	      const text = m.params.args.map((a) => a.value ?? a.description ?? "").join(" ");
558	      consoleLines.push(`${m.params.type}: ${text}`.slice(0, 300));
559	    }
560	    if (m.method === "Runtime.exceptionThrown") {
561	      consoleLines.push(`exception: ${m.params.exceptionDetails?.exception?.description ?? m.params.exceptionDetails?.text}`.slice(0, 300));
562	    }
563	    for (const fn of listeners.get(m.method) ?? []) fn(m.params);
564	  };
565	  const send = (method, params = {}) =>
566	    new Promise((resolve) => {
567	      const id = ++seq;
568	      pending.set(id, resolve);
569	      ws.send(JSON.stringify({ id, method, params }));
570	    });
571	  const on = (method, fn) => {
572	    if (!listeners.has(method)) listeners.set(method, []);
573	    listeners.get(method).push(fn);
574	  };
575	  const js = async (expression) => {
576	    const r = await send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
577	    if (r.result?.exceptionDetails) throw new Error(r.result.exceptionDetails.exception?.description ?? r.result.exceptionDetails.text);
578	    return r.result?.result?.value;
579	  };
580	  await send("Runtime.enable");
581	  await send("Page.enable");
582	  await send("Emulation.setDeviceMetricsOverride", { width, height, deviceScaleFactor: 1, mobile: width < 700 });
583	
584	  const api = {
585	    send,
586	    js,
587	    on,
588	    consoleLines,
589	    async goto(url, settle = 4000) {
590	      await send("Page.navigate", { url });
591	      await sleep(settle);
592	    },
593	    click: (text, scope = "button") =>
594	      js(`(() => { const b = [...document.querySelectorAll(${JSON.stringify(scope)})].find((b) => b.textContent.trim().startsWith(${JSON.stringify(text)}) && !b.disabled); if (!b) return false; b.click(); return true; })()`),
595	    /** Bounding rect (CSS px, viewport-relative) of the element an expression returns. */
596	    rectOf: (finder) =>
597	      js(`(() => { const e = ${finder}; if (!e) return null; const r = e.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), width: Math.round(r.width), height: Math.round(r.height) }; })()`),
598	    rect: (selector) => api.rectOf(`document.querySelector(${JSON.stringify(selector)})`),
599	    /**
600	     * PNG of the viewport, or of one element (a JS expression returning it). The
601	     * clip is in CSS px; the image comes back at the window's device scale.
602	     */
603	    async shot(path, finder, { beyond = false } = {}) {
604	      let clip = finder ? await api.rectOf(finder) : null;
605	      if (finder && !clip) throw new Error("shot: element not found: " + finder.slice(0, 80));
606	      // Beyond the viewport the clip is in document coordinates.
607	      if (clip && beyond) clip = { ...clip, ...(await js(`({ x: ${clip.x} + scrollX, y: ${clip.y} + scrollY })`)) };
608	      const r = await send(
609	        "Page.captureScreenshot",
610	        clip ? { format: "png", clip: { ...clip, scale: 1 }, captureBeyondViewport: beyond } : { format: "png" },
611	      );
612	      writeFileSync(path, Buffer.from(r.result.data, "base64"));
613	    },
614	    /** Records the page as JPEG frames into `dir`; returns stop() -> frame list [{file, t}]. */
615	    async screencast(dir) {
616	      mkdirSync(dir, { recursive: true });
617	      const frames = [];
618	      let active = true;
619	      on("Page.screencastFrame", (p) => {
620	        if (!active) return;
621	        const file = join(dir, `f${String(frames.length).padStart(5, "0")}.jpg`);
622	        writeFileSync(file, Buffer.from(p.data, "base64"));
623	        frames.push({ file, t: p.metadata.timestamp });
624	        send("Page.screencastFrameAck", { sessionId: p.sessionId });
625	      });
626	      await send("Page.startScreencast", { format: "jpeg", quality: 88, everyNthFrame: 1 });
627	      return async () => {
628	        active = false;
629	        await send("Page.stopScreencast");
630	        // A still page sends no new frames: hold the last one until the stop, so
631	        // the clip keeps its full wall-clock length.
632	        if (frames.length) frames.push({ file: frames[frames.length - 1].file, t: Date.now() / 1000 });
633	        writeFileSync(join(dir, "frames.json"), JSON.stringify(frames));
634	        return frames;
635	      };
636	    },
637	    close() {
638	      try { ws.close(); } catch {}
639	      chrome.kill("SIGKILL");
640	    },
641	  };
642	  return api;
643	}
644	
645	/** ffmpeg concat list with real per-frame durations, so the clip plays at wall-clock speed. */
646	export function concatList(frames, speed = 1) {
647	  let out = "";
648	  for (let i = 0; i < frames.length; i++) {
649	    const next = frames[i + 1];
650	    const d = next ? Math.max(0.01, (next.t - frames[i].t) / speed) : 0.1;
651	    out += `file '${frames[i].file}'\nduration ${d.toFixed(3)}\n`;
652	  }
653	  if (frames.length) out += `file '${frames[frames.length - 1].file}'\n`;
654	  return out;
655	}
