/* Bulwark design system: monochrome, editorial, precise.
   Ink on paper, Inter 300 for display, pill controls, generous whitespace.
   Colour carries meaning only: pass / broke a rule / crash / hang / runaway,
   and the resilience gradient. Shared by the landing page and the app. */
:root {
  --bg: #ffffff;
  --bg-2: #fafafa;
  --surface: #ffffff;
  --surface-muted: #f4f4f6;
  --surface-inverse: #0a0a0a;

  --fg: #0a0a0a;
  --fg-muted: rgba(10, 10, 10, 0.56);
  --fg-dim: rgba(10, 10, 10, 0.38);
  --fg-inverse: #ffffff;
  --fg-inverse-muted: rgba(255, 255, 255, 0.58);

  --line: rgba(0, 0, 0, 0.08);
  --line-strong: rgba(0, 0, 0, 0.12);
  --line-bold: rgba(0, 0, 0, 0.35);
  --line-inverse: rgba(255, 255, 255, 0.12);

  /* Meaning */
  --pass: #15803d;
  --pass-soft: rgba(21, 128, 61, 0.08);
  --broken: #b45309;
  --broken-soft: rgba(180, 83, 9, 0.08);
  --crash: #dc2626;
  --crash-soft: rgba(220, 38, 38, 0.08);
  --hung: #6d28d9;
  --runaway: #be185d;
  --pending: #e7e7ea;
  --resilience-grad: linear-gradient(90deg, #ef4444 0%, #f59e0b 45%, #10b981 100%);

  /* Agents: one quiet mark each */
  --red-agent: #dc2626;
  --blue-agent: #1d4ed8;
  --judge-agent: #0a0a0a;
  --guard: #0f766e;

  --radius-sm: 12px;
  --radius: 20px;
  --radius-lg: 28px;
  --pill: 999px;
  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.04), 0 8px 24px -12px rgba(0, 0, 0, 0.12);
  --shadow-lg: 0 2px 4px rgba(0, 0, 0, 0.04), 0 24px 60px -24px rgba(0, 0, 0, 0.25);

  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);

  --font-sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-mono: 'Geist Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

  color-scheme: light;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { max-width: 100vw; overflow-x: clip; }
html { scroll-behavior: smooth; }
body {
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font-sans);
  font-weight: 400;
  line-height: 1.5;
  letter-spacing: -0.005em;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
h1, h2, h3 { font-weight: 300; letter-spacing: -0.035em; line-height: 1.04; }
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; cursor: pointer; border: none; background: none; }
code, kbd, .mono { font-family: var(--font-mono); font-size: 0.92em; letter-spacing: 0; }
::selection { background: #0a0a0a; color: #fff; }
:focus-visible { outline: 2px solid #0a0a0a; outline-offset: 2px; border-radius: 6px; }

