    $('bigscore').innerHTML = arrow(pct(s.overallBefore), pct(s.overallAfter));
    $('resultline').textContent = `Fixed ${s.fixed.length} · skipped ${s.skipped.length} · unfixed ${s.unfixed.length} · ${s.attempts} attempts, ${s.rollbacks} rollbacks`;
    $('resultrisk').innerHTML = L.riskBefore != null && L.riskAfter != null
      ? `<b>${money(L.riskBefore)} → ${money(L.riskAfter)}</b><span>at risk per 1,000 tickets</span>` +
        (s.cost ? `<span style="display:block;margin-top:4px">this run cost ${'$' + Number(s.cost.totalUsd).toFixed(4)} (LLM ${'$' + Number(s.cost.llmUsd).toFixed(4)})</span>` : '')
      : '';
    $('badge').src = '/badge.svg?t=' + Date.now();
    const art = (file, label) => `<a href="/api/artifact?run=${encodeURIComponent(s.runId)}&file=${encodeURIComponent(file)}" target="_blank" rel="noopener">${esc(label)}</a>`;
    $('links').innerHTML = [art('PR.md', 'PR description'), art('fix.patch', 'fix.patch'), art('scorecard-before.md', 'Scorecard before'), art('scorecard-after.md', 'Scorecard after'),
      ...s.artifacts.postmortems.map((p) => { const f = p.split('/').pop(); return art(f, f.replace('postmortem-', 'Postmortem: ').replace('.md', '')); })].join('');
    L.before = s.overallBefore; L.after = s.overallAfter;
    attempts = s.attempts; rollbacks = s.rollbacks;
    loopStats();
    tl(`<b>Done.</b> Resilience ${pct(s.overallBefore)} → ${pct(s.overallAfter)}. Artifacts in <code>${esc(s.dir)}</code>`);
  },
};

